import jsPDF from "jspdf";

/**
 * Logo Oficial Tensacon S.A. en Base64 (PNG recortado y optimizado)
 * Listo para usar en jsPDF (doc.addImage) en modo monocromo o color.
 * Dimensiones: 970 x 230 px (aspect ratio: 4.217 : 1)
 */
export const LOGO_TENSACON_BASE64 = "data:image/png;base64,";
export const LOGO_TENSACON_RATIO = 970 / 230; // ~4.217

export interface OpcionesEncabezadoPdf {
  folio?: string;
  subtitulo?: string;
  fecha?: string;
  marginLeft?: number;
  marginRight?: number;
  startY?: number;
}

/**
 * Dibuja el encabezado estándar corporativo de Tensacon S.A. optimizado para
 * impresión monocromática (blanco y negro / escala de grises de alto contraste).
 * 
 * Reglas corporativas:
 * - Logo oficial corporativo Tensacon (nuevo logo TC.png)
 * - Sin fondos negros saturados que manchen o gasten tóner
 * - Divisores nítidos (#cbd5e1 / #334155)
 * - Tipografía negra #000000 de alta legibilidad
 * 
 * @returns La posición Y libre para continuar dibujando el contenido.
 */
export function dibujarEncabezadoCorporativoPdf(
  doc: jsPDF,
  opciones: OpcionesEncabezadoPdf = {}
): number {
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginLeft = opciones.marginLeft ?? 14;
  const marginRight = opciones.marginRight ?? 14;
  let yPos = opciones.startY ?? 10;

  // 1. Logo oficial corporativo Tensacon
  const logoHeight = 9.5;
  const logoWidth = logoHeight * LOGO_TENSACON_RATIO; // ~40.06 mm
  try {
    doc.addImage(LOGO_TENSACON_BASE64, "PNG", marginLeft, yPos, logoWidth, logoHeight);
  } catch (err) {
    // Respaldo de texto si la imagen falla
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text("TENSACON S.A.", marginLeft, yPos + 6);
  }

  // Subtítulo del departamento / módulo
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(51, 65, 85); // slate-700
  const subtitulo = opciones.subtitulo || "Sistema de Gestión y Control de Bodega (WMS)";
  doc.text(`|   ${subtitulo}`, marginLeft + logoWidth + 2.5, yPos + 6.5);

  // 2. Derecha: Folio y Fecha
  if (opciones.folio) {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9.5);
    doc.setTextColor(0, 0, 0);
    doc.text(opciones.folio, pageWidth - marginRight, yPos + 4.5, { align: "right" });
  }

  if (opciones.fecha) {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.5);
    doc.setTextColor(71, 85, 105);
    doc.text(`Fecha: ${opciones.fecha}`, pageWidth - marginRight, yPos + 8.5, { align: "right" });
  }

  // 3. Línea divisoria corporativa de alto contraste
  yPos += logoHeight + 2.5;
  doc.setDrawColor(203, 213, 225); // #cbd5e1 (borde estándar corporativo)
  doc.setLineWidth(0.4);
  doc.line(marginLeft, yPos, pageWidth - marginRight, yPos);

  return yPos + 4;
}